dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "summary_data",
      "header": "Summary Data",
      "data point": {
        "type": "file",
        "initial load": "https://hugeampkpncms.org/sites/default/files/users/user32/calrep_v9.csv",
        "data type": "csv"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Experiment ID",
            "raw field": "experiment_id"
          },
          {
            "type": "raw",
            "field name": "Subject ID",
            "raw field": "subject_id"
          },
          {
            "type": "raw",
            "field name": "Designation",
            "raw field": "designation"
          },
          {
            "type": "raw",
            "field name": "Total Mass (g)",
            "raw field": "total_mass"
          },
          {
            "type": "raw",
            "field name": "Expt. Start",
            "raw field": "exp_time_start"
          },
          {
            "type": "raw",
            "field name": "Expt. End",
            "raw field": "exp_time_end"
          },
          {
            "type": "raw",
            "field name": "Time of Day",
            "raw field": "tod"
          },
          {
            "type": "raw",
            "field name": "Group",
            "raw field": "group"
          },
          {
            "type": "raw",
            "field name": "Food Intake (kcal/hr)",
            "raw field": "food"
          },
          {
            "type": "raw",
            "field name": "Energy Expenditure (kcal/hr)",
            "raw field": "ee"
          },
          {
            "type": "raw",
            "field name": "Oxygen Consumption (ml/hr)",
            "raw field": "vo2"
          },
          {
            "type": "raw",
            "field name": "Carbon Dioxide Production (ml/hr)",
            "raw field": "vco2"
          },
          {
            "type": "raw",
            "field name": "Respiratory Exchange Ratio",
            "raw field": "rer"
          },
          {
            "type": "raw",
            "field name": "Locomotor Activity (beam breaks/hr)",
            "raw field": "loco"
          },
          {
            "type": "raw",
            "field name": "Energy Balance (kcal/hr)",
            "raw field": "eb"
          },
          {
            "type": "raw",
            "field name": "Ambient Temp. (C)",
            "raw field": "temperature"
          },
          {
            "type": "raw",
            "field name": "Age (weeks)",
            "raw field": "age"
          },
          {
            "type": "raw",
            "field name": "Duration (hrs)",
            "raw field": "duration_hr"
          },
          {
            "type": "raw",
            "field name": "Food Name",
            "raw field": "diet_names"
          },
          {
            "type": "raw",
            "field name": "Food Density (kcal/g)",
            "raw field": "dietCal"
          },
          {
            "type": "raw",
            "field name": "Strain",
            "raw field": "strain"
          },
          {
            "type": "raw",
            "field name": "Genetic Background",
            "raw field": "genetic_background"
          },
          {
            "type": "raw",
            "field name": "Location",
            "raw field": "location"
          },
          {
            "type": "raw",
            "field name": "System",
            "raw field": "system"
          },
          {
            "type": "raw",
            "field name": "Lean Mass (g)",
            "raw field": "lean_mass"
          },
          {
            "type": "raw",
            "field name": "Fat Mass (g)",
            "raw field": "fat_mass"
          },
          {
            "type": "raw",
            "field name": "Ambulatory Activity (beam breaks/hr)",
            "raw field": "ped"
          },
          {
            "type": "raw",
            "field name": "Body Temp. (C)",
            "raw field": "bodytemp"
          },
          {
            "type": "raw",
            "field name": "Distance",
            "raw field": "distance"
          },
          {
            "type": "raw",
            "field name": "Water Intake (ml/hr)",
            "raw field": "water"
          },
          {
            "type": "raw",
            "field name": "Sex",
            "raw field": "sex"
          },
          {
            "type": "raw",
            "field name": "Quality Score",
            "raw field": "quality_score"
          },
          {
            "type": "raw",
            "field name": "pmid",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Investigator",
            "raw field": "investigator"
          },
          {
            "type": "raw",
            "field name": "Treatment",
            "raw field": "treatment"
          },
          {
            "type": "raw",
            "field name": "Total Mass 2 (g)",
            "raw field": "total_mass_2"
          },
          {
            "type": "raw",
            "field name": "Zygosity",
            "raw field": "zygosity"
          },
          {
            "type": "replace characters",
            "field name": "Time of day",
            "raw field": "tod",
            "replace": [
              {
                "from": "Light",
                "to": "<span class='v-light'>Light</span>"
              },
              {
                "from": "Dark",
                "to": "<span class='v-dark'>Dark</span>"
              },
              {
                "from": "Full day",
                "to": "<span class='v-fullday'>Full Day</span>"
              }
            ]
          },
          {
            "type": "join multi",
            "field name": "eID-sID-s-a",
            "fields to join": [
              "tod",
              "subject_id",
              "sex",
              "age"
            ],
            "join by": [
              " [",
              "] ",
              ", "
            ]
          },
          {
            "type": "join multi",
            "field name": "Experiment Subject",
            "fields to join": [
              "experiment_id",
              "subject_id"
            ],
            "join by": [
              ": "
            ]
          }
        ],
        "top rows": [
          "Experiment ID",
          "Time of day",
          "Subject ID",
          "Sex",
          "Age (weeks)",
          "Total Mass (g)",
          "Ambient Temp. (C)",
          "Group",
          "Strain",
          "Treatment",
          "Genetic Background"
        ],
        "features": [
          "Subject",
          "Expt.",
          "Results"
        ],
        "Subject": [
          "Lean Mass (g)",
          "Fat Mass (g)",
          "Body Temp. (C)",
          "Quality Score",
          "System",
          "Zygosity",
          "Designation"
        ],
        "Expt.": [
          "Food Name",
          "Food Density (kcal/g)",
          "Duration (hrs)",
          "Distance",
          "Water Intake (ml/hr)",
          "Location",
          "Investigator"
        ],
        "Results": [
          "Energy Expenditure (kcal/hr)",
          "Food Intake (kcal/hr)",
          "Oxygen Consumption (ml/hr)",
          "Carbon Dioxide Production (ml/hr)",
          "Respiratory Exchange Ratio",
          "Locomotor Activity (beam breaks/hr)",
          "Energy Balance (kcal/hr)",
          "Ambulatory Activity (beam breaks/hr)"
        ]
      },
      "visualizers": {
        "wrapper type": "divs",
        "visualizers": [
          {
            "label": "Single + Options",
            "type": "scatter plot",
            "render type": "single plot",
            "x axis fields": [
              "Total Mass (g)",
              "Lean Mass (g)",
              "Fat Mass (g)",
              "Age (weeks)"
            ],
            "y axis fields": [
              "Energy Expenditure (kcal/hr)",
              "Respiratory Exchange Ratio",
              "Food Intake (kcal/hr)",
              "Locomotor Activity (beam breaks/hr)",
              "Energy Balance (kcal/hr)",
              "Oxygen Consumption (ml/hr)"
            ],
            "color by": [
              "Experiment ID",
              "Sex",
              "Time of Day",
              {"field": "Ambient Temp. (C)", "type": "gradient"},
              "Group",
              {"field": "Food Density (kcal/g)", "type": "gradient", "color_scale": "cividis"},
              "Treatment",
              {"field": "Duration (hrs)", "type": "gradient"}
            ],
            "render by": "Experiment Subject",
            "hover content": [
              "Sex",
              "Age (weeks)",
              "Total Mass (g)",
              "Energy Expenditure (kcal/hr)"
            ],
            "ticks decimal point": "2",
            "height": 390,
            "width": 450,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          }
        ]
      },
      "filters": [
        {
          "field": "Age (weeks)",
          "label": "Age (weeks)",
          "type": "slider",
          "slider type": "dual"
        },
        {
          "field": "Ambient Temp. (C)",
          "label": "Ambient Temp. (C)",
          "type": "slider",
          "slider type": "dual"
        },
        {
          "field": "Quality Score",
          "label": "Quality Score",
          "type": "checkbox"
        },
        {
          "field": "Time of Day",
          "label": "Time of Day",
          "type": "checkbox"
        },
        {
          "field": "Total Mass (g)",
          "label": "Total Mass (g)",
          "type": "slider",
          "slider type": "dual"
        },
        {
          "field": "Strain",
          "label": "Strain",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Genetic Background",
          "label": "Genetic Background",
          "type": "checkbox"
        },
        {
          "field": "Food Density (kcal/g)",
          "label": "Food density (kcal/g)",
          "type": "slider",
          "slider type": "dual"
        },
        {
          "field": "Experiment ID",
          "label": "Experiment ID",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Group",
          "label": "Group",
          "type": "checkbox"
        }
      ]
    }
  ]
}
